 61	\section{The pulled-apart measurements and observables}
 62	
 63	The measurement $\{\hat{S}_{g_X,g_Z}\}$ reads out an $X$-polynomial and a $Z$-polynomial simultaneously. We now separate the two readings again, this time as commuting actions on distinct registers: the polynomial outcome is measured on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), while a genuine Pauli measurement acts on the EPR register $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
 64	
 65	\begin{definition}[Single-basis marginals of the polynomial-pair measurement]\label{def:s-w-marginals}
 66		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly}
 67		\leanok
 68		\uses{lem:qld-4-7}
 69		Let $\{\hat{S}_{g_X,g_Z}\}$ be the projective measurement of Lemma~\ref{lem:qld-4-7}. For every $g \in \mathrm{ideg}_{d,m}(\F_q)$ define
 70		\[
 71			\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
 72			\qquad \text{and} \qquad
 73			\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
 74		\]
 75		the sums ranging over $\mathrm{ideg}_{d,m}(\F_q)$.
220		\begin{equation}\label{eq:qld-nonencoding-mass}
221		\sum_{g \,\text{not an encoding}} \bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} \,\leq\, O(\delta_G + \eps) + \frac{md}{q} \,\leq\, \delta_P\;,
222		\end{equation}
223		and symmetrically with the registers $\mathrm{A}\mathrm{A}'$ in place of $\mathrm{B}\mathrm{B}'$. (If $d = 0$, every element of $\mathrm{ideg}_{d,m}(\F_q)$ is constant, hence an encoding, and the left-hand side vanishes.)
224	
